<div class="page-heading"><div><p class="eyebrow">SEGURANÇA E OPERAÇÃO</p><h1>Auditoria</h1><p class="muted">Ações administrativas recentes da sua organização.</p></div></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Data e hora</th><th>Usuário</th><th>Ação</th><th>Detalhes</th><th>Endereço</th></tr></thead><tbody><?php foreach($data['logs'] as $log): ?><tr><td><?=e(date('d/m/Y H:i:s',strtotime($log['created_at'])))?></td><td><?=e($log['user_id']?:'Sistema')?></td><td><b><?=e($log['action'])?></b></td><td><code><?=e($log['details'])?></code></td><td><?=e($log['ip'])?></td></tr><?php endforeach; ?></tbody></table><?php if(!$data['logs']): ?><div class="empty-state">Nenhuma ação registrada.</div><?php endif; ?></div></section>
